changeSet.sql:
ALTER TABLE clinlims.alert
  ADD CONSTRAINT chk_alert_entity_id_or_ref
  CHECK (
    (alert_entity_id IS NOT NULL AND alert_entity_ref IS NULL)
    OR (alert_entity_id IS NULL AND alert_entity_ref IS NOT NULL)
  );

ALTER TABLE clinlims.alert DROP CONSTRAINT IF EXISTS chk_alert_type;
ALTER TABLE clinlims.alert ADD CONSTRAINT chk_alert_type
CHECK (alert_type IN (
  'FREEZER_TEMPERATURE', 'EQUIPMENT_FAILURE', 'INVENTORY_LOW', 'SAMPLE_TRACKING', 'OTHER',
  'EQA_DEADLINE', 'SAMPLE_EXPIRATION', 'STAT_UPCOMING', 'STAT_OVERDUE', 'CRITICAL_UNACKNOWLEDGED',
  'MICROBIOLOGY_CRITICAL'
));

rollback.sql:
ALTER TABLE clinlims.alert DROP CONSTRAINT chk_alert_type;
ALTER TABLE clinlims.alert ADD CONSTRAINT chk_alert_type
CHECK (alert_type IN (
  'FREEZER_TEMPERATURE', 'EQUIPMENT_FAILURE', 'INVENTORY_LOW', 'SAMPLE_TRACKING', 'OTHER',
  'EQA_DEADLINE', 'SAMPLE_EXPIRATION', 'STAT_UPCOMING', 'STAT_OVERDUE', 'CRITICAL_UNACKNOWLEDGED'
));
ALTER TABLE clinlims.alert DROP CONSTRAINT chk_alert_entity_id_or_ref;
